  logic [LPARA_DATA_W-1:0] w_tmr_c4_ow_value;
  logic w_we_tmr_c4_ow_h;
  logic [31:0] reg_tmr_c4_ow_h_hi;
  logic [31:0] w_tmr_c4_ow_h_hi_nxt;
  logic [LPARA_DATA_W-1:0] w_tmr_c4_ow_h_value;
  logic w_we_tmr_c5_ow;
  logic [31:0] reg_tmr_c5_ow_width;
  logic [31:0] w_tmr_c5_ow_width_nxt;
  logic [LPARA_DATA_W-1:0] w_tmr_c5_ow_value;
  logic w_we_tmr_c5_ow_h;
  logic [31:0] reg_tmr_c5_ow_h_hi;
  logic [31:0] w_tmr_c5_ow_h_hi_nxt;
  logic [LPARA_DATA_W-1:0] w_tmr_c5_ow_h_value;
  logic w_we_tmr_c6_ow;
  logic [31:0] reg_tmr_c6_ow_width;
  logic [31:0] w_tmr_c6_ow_width_nxt;
  logic [LPARA_DATA_W-1:0] w_tmr_c6_ow_value;
  logic w_we_tmr_c6_ow_h;
  logic [31:0] reg_tmr_c6_ow_h_hi;
  logic [31:0] w_tmr_c6_ow_h_hi_nxt;
  logic [LPARA_DATA_W-1:0] w_tmr_c6_ow_h_value;
  logic w_we_tmr_c7_ow;
  logic [31:0] reg_tmr_c7_ow_width;
  logic [31:0] w_tmr_c7_ow_width_nxt;
  logic [LPARA_DATA_W-1:0] w_tmr_c7_ow_value;
  logic w_we_tmr_c7_ow_h;
  logic [31:0] reg_tmr_c7_ow_h_hi;
  logic [31:0] w_tmr_c7_ow_h_hi_nxt;
  logic [LPARA_DATA_W-1:0] w_tmr_c7_ow_h_value;
  logic [LPARA_DATA_W-1:0] w_tmr_dma_sts_value;

  // The parameter selects the register clock/reset for the chosen bus front end.
  assign w_clk_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_clk_reg : i_clk_apb;
  assign w_rst_n_reg = (PARA_ASYNCHRONOUS == 32'd1) ? i_rst_n_reg : i_rst_n_apb;


  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb[LPARA_STRB_W-1:0] & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Write byte strobes are captured with the write payload and expanded to field-bit masks.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wstrb
    if (!i_rst_n_apb)
      reg_wstrb <= '0;
    else if (w_apb_wr)
      reg_wstrb <= i_apb_pstrb[LPARA_STRB_W-1:0];
  end
  generate
    for (genvar gen_lane = 0; gen_lane < LPARA_STRB_W; gen_lane++) begin : gen_apb_wmask
      assign w_wmask[(gen_lane * 8) +: 8] = {8{reg_wstrb[gen_lane]}};
    end
  endgenerate

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Per-register write/read address enables.
  assign w_we_tmr_ctrl = w_wr_en & (reg_addr == LPARA_TMR_CTRL_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_period = w_wr_en & (reg_addr == LPARA_TMR_PERIOD_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_period_hi = w_wr_en & (reg_addr == LPARA_TMR_PERIOD_HI_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_prescale = w_wr_en & (reg_addr == LPARA_TMR_PRESCALE_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_dma_cfg = w_wr_en & (reg_addr == LPARA_TMR_DMA_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch0_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH0_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch1_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH1_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch2_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH2_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch3_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH3_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch4_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH4_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch5_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH5_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch6_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH6_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch7_cfg = w_wr_en & (reg_addr == LPARA_TMR_CH7_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch0_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH0_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c0_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C0_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch1_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH1_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c1_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C1_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch2_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH2_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c2_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C2_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch3_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH3_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c3_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C3_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch4_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH4_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c4_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C4_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch5_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH5_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c5_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C5_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch6_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH6_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c6_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C6_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_ch7_cmp = w_wr_en & (reg_addr == LPARA_TMR_CH7_CMP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c7_cmp_h = w_wr_en & (reg_addr == LPARA_TMR_C7_CMP_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_irq_raw0 = w_wr_en & (reg_addr == LPARA_TMR_IRQ_RAW0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_irq_en0 = w_wr_en & (reg_addr == LPARA_TMR_IRQ_EN0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_irq_inj0 = w_wr_en & (reg_addr == LPARA_TMR_IRQ_INJ0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_irq_raw1 = w_wr_en & (reg_addr == LPARA_TMR_IRQ_RAW1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_irq_en1 = w_wr_en & (reg_addr == LPARA_TMR_IRQ_EN1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_irq_inj1 = w_wr_en & (reg_addr == LPARA_TMR_IRQ_INJ1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c0_tout = w_wr_en & (reg_addr == LPARA_TMR_C0_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c0_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C0_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c1_tout = w_wr_en & (reg_addr == LPARA_TMR_C1_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c1_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C1_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c2_tout = w_wr_en & (reg_addr == LPARA_TMR_C2_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c2_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C2_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c3_tout = w_wr_en & (reg_addr == LPARA_TMR_C3_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c3_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C3_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c4_tout = w_wr_en & (reg_addr == LPARA_TMR_C4_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c4_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C4_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c5_tout = w_wr_en & (reg_addr == LPARA_TMR_C5_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c5_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C5_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c6_tout = w_wr_en & (reg_addr == LPARA_TMR_C6_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c6_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C6_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c7_tout = w_wr_en & (reg_addr == LPARA_TMR_C7_TOUT_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c7_tout_h = w_wr_en & (reg_addr == LPARA_TMR_C7_TOUT_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_pi_cfg = w_wr_en & (reg_addr == LPARA_TMR_PI_CFG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_pi_sts = w_wr_en & (reg_addr == LPARA_TMR_PI_STS_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c0_ow = w_wr_en & (reg_addr == LPARA_TMR_C0_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c0_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C0_OW_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c1_ow = w_wr_en & (reg_addr == LPARA_TMR_C1_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c1_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C1_OW_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c2_ow = w_wr_en & (reg_addr == LPARA_TMR_C2_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c2_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C2_OW_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c3_ow = w_wr_en & (reg_addr == LPARA_TMR_C3_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c3_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C3_OW_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c4_ow = w_wr_en & (reg_addr == LPARA_TMR_C4_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c4_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C4_OW_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c5_ow = w_wr_en & (reg_addr == LPARA_TMR_C5_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c5_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C5_OW_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c6_ow = w_wr_en & (reg_addr == LPARA_TMR_C6_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c6_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C6_OW_H_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c7_ow = w_wr_en & (reg_addr == LPARA_TMR_C7_OW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_tmr_c7_ow_h = w_wr_en & (reg_addr == LPARA_TMR_C7_OW_H_OFFSET[LPARA_ADDR_W-1:0]);

  // Register transaction events are qualified by the captured APB transfer.
  // Read events include aligned unmapped reads, which return zero. Unaligned reads
  // are suppressed even when the APB error response is disabled.
  assign o_reg_rd_en   = w_rd_en & (reg_addr[1:0] == 2'b00);
  assign o_reg_rd_addr = o_reg_rd_en ? reg_addr : '0;

  // Write events are asserted only for a mapped register with at least one
  // software-writable field; rejected and read-only writes do not assert this event.
  assign o_reg_wr_en   =
    (|w_we_tmr_ctrl)
    | (|w_we_tmr_period)
    | (|w_we_tmr_period_hi)
    | (|w_we_tmr_prescale)
    | (|w_we_tmr_dma_cfg)
    | (|w_we_tmr_ch0_cfg)
    | (|w_we_tmr_ch1_cfg)
    | (|w_we_tmr_ch2_cfg)
    | (|w_we_tmr_ch3_cfg)
    | (|w_we_tmr_ch4_cfg)
    | (|w_we_tmr_ch5_cfg)
    | (|w_we_tmr_ch6_cfg)
    | (|w_we_tmr_ch7_cfg)
    | (|w_we_tmr_ch0_cmp)
    | (|w_we_tmr_c0_cmp_h)
    | (|w_we_tmr_ch1_cmp)
    | (|w_we_tmr_c1_cmp_h)
    | (|w_we_tmr_ch2_cmp)
    | (|w_we_tmr_c2_cmp_h)
    | (|w_we_tmr_ch3_cmp)
    | (|w_we_tmr_c3_cmp_h)
    | (|w_we_tmr_ch4_cmp)
    | (|w_we_tmr_c4_cmp_h)
    | (|w_we_tmr_ch5_cmp)
    | (|w_we_tmr_c5_cmp_h)
    | (|w_we_tmr_ch6_cmp)
    | (|w_we_tmr_c6_cmp_h)
    | (|w_we_tmr_ch7_cmp)
    | (|w_we_tmr_c7_cmp_h)
    | (|w_we_tmr_irq_raw0)
    | (|w_we_tmr_irq_en0)
    | (|w_we_tmr_irq_inj0)
    | (|w_we_tmr_irq_raw1)
    | (|w_we_tmr_irq_en1)
    | (|w_we_tmr_irq_inj1)
    | (|w_we_tmr_c0_tout)
    | (|w_we_tmr_c0_tout_h)
    | (|w_we_tmr_c1_tout)
    | (|w_we_tmr_c1_tout_h)
    | (|w_we_tmr_c2_tout)
    | (|w_we_tmr_c2_tout_h)
    | (|w_we_tmr_c3_tout)
    | (|w_we_tmr_c3_tout_h)
    | (|w_we_tmr_c4_tout)
    | (|w_we_tmr_c4_tout_h)
    | (|w_we_tmr_c5_tout)
    | (|w_we_tmr_c5_tout_h)
    | (|w_we_tmr_c6_tout)
    | (|w_we_tmr_c6_tout_h)
    | (|w_we_tmr_c7_tout)
    | (|w_we_tmr_c7_tout_h)
    | (|w_we_tmr_pi_cfg)
    | (|w_we_tmr_pi_sts)
    | (|w_we_tmr_c0_ow)
    | (|w_we_tmr_c0_ow_h)
    | (|w_we_tmr_c1_ow)
    | (|w_we_tmr_c1_ow_h)
    | (|w_we_tmr_c2_ow)
    | (|w_we_tmr_c2_ow_h)
    | (|w_we_tmr_c3_ow)
    | (|w_we_tmr_c3_ow_h)
    | (|w_we_tmr_c4_ow)
    | (|w_we_tmr_c4_ow_h)
    | (|w_we_tmr_c5_ow)
    | (|w_we_tmr_c5_ow_h)
    | (|w_we_tmr_c6_ow)
    | (|w_we_tmr_c6_ow_h)
    | (|w_we_tmr_c7_ow)
    | (|w_we_tmr_c7_ow_h);
  assign o_reg_wr_addr = o_reg_wr_en ? reg_addr : '0;

  // Elaboration selects one clock architecture for this single RTL module.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_csr

      // Async-only request, acknowledge, and synchronizer state.
      logic w_rd_ack;
      logic w_rd_ack_bus;
      logic reg_rd_req;
      logic w_rd_req_nxt;
      logic reg_rd_ack_bus_dly;
      logic w_wr_ack;
      logic w_wr_ack_bus;
      logic reg_wr_req;
      logic w_wr_req_nxt;
      logic w_wr_ack_fall;
      logic reg_wr_ack_bus_dly;
      logic w_rd_req_reg;
      logic reg_rd_req_reg_dly;
      logic w_wr_req_reg;
      logic reg_wr_req_reg_dly;
      logic w_pready_nxt;
      logic reg_pready;

      // Read request and acknowledge toggles cross between the APB and register clocks.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_rd_ack),
        .o_q         (w_rd_ack_bus)
      );

      // APB read request is set on a read and cleared by its synchronized acknowledge.
      assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
      assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
        if (!i_rst_n_apb) begin
          reg_rd_req         <= 1'b0;
          reg_rd_ack_bus_dly <= 1'b0;
        end else begin
          reg_rd_req         <= w_rd_req_nxt;
          reg_rd_ack_bus_dly <= w_rd_ack_bus;
        end
      end

      // APB write request uses an independent request/acknowledge toggle.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_wr_ack_sync (
        .i_clk_dst   (i_clk_apb),
        .i_rst_n_dst (i_rst_n_apb),
        .i_d         (w_wr_ack),
        .o_q         (w_wr_ack_bus)
      );
      assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
      assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
        if (!i_rst_n_apb) begin
          reg_wr_req         <= 1'b0;
          reg_wr_ack_bus_dly <= 1'b0;
        end else begin
          reg_wr_req         <= w_wr_req_nxt;
          reg_wr_ack_bus_dly <= w_wr_ack_bus;
        end
      end

      // Read request is synchronized into the register clock domain.
      m_vlsit_csr_sync #(
        .PARA_LEVELS (LPARA_SYNC_STAGES)
      ) u_rd_req_sync (
        .i_clk_dst   (i_clk_reg),
