  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_tmr_c7_ow
    if (!w_rst_n_reg) begin
      reg_tmr_c7_ow_width <= 32'h0;
    end else begin
      reg_tmr_c7_ow_width <= w_tmr_c7_ow_width_nxt;
    end
  end

  // Register tmr_c7_ow: output ports follow the flops.
  assign o_tmr_c7_ow_width = reg_tmr_c7_ow_width;

  // Register tmr_c7_ow: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_tmr_c7_ow_value
    w_tmr_c7_ow_value = '0;
    w_tmr_c7_ow_value[31:0] = reg_tmr_c7_ow_width;
  end

  // tmr_c7_ow_h_hi next value (rw): update only byte lanes selected by the bus strobe.
  assign w_tmr_c7_ow_h_hi_nxt = (w_we_tmr_c7_ow_h & (|w_wmask[31:0])) ? ((reg_wdata[31:0] & w_wmask[31:0]) | (reg_tmr_c7_ow_h_hi & ~w_wmask[31:0])) : reg_tmr_c7_ow_h_hi;

  // Register tmr_c7_ow_h: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_tmr_c7_ow_h
    if (!w_rst_n_reg) begin
      reg_tmr_c7_ow_h_hi <= 32'h0;
    end else begin
      reg_tmr_c7_ow_h_hi <= w_tmr_c7_ow_h_hi_nxt;
    end
  end

  // Register tmr_c7_ow_h: output ports follow the flops.
  assign o_tmr_c7_ow_h_hi = reg_tmr_c7_ow_h_hi;

  // Register tmr_c7_ow_h: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_tmr_c7_ow_h_value
    w_tmr_c7_ow_h_value = '0;
    w_tmr_c7_ow_h_value[31:0] = reg_tmr_c7_ow_h_hi;
  end

  // Register tmr_dma_sts: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_tmr_dma_sts_value
    w_tmr_dma_sts_value = '0;
    w_tmr_dma_sts_value[0] = i_tmr_dma_sts_cap_req;
    w_tmr_dma_sts_value[1] = i_tmr_dma_sts_cap_burst;
    w_tmr_dma_sts_value[2] = i_tmr_dma_sts_cap_clr_busy;
    w_tmr_dma_sts_value[3] = i_tmr_dma_sts_cmp_req;
    w_tmr_dma_sts_value[4] = i_tmr_dma_sts_cmp_burst;
    w_tmr_dma_sts_value[5] = i_tmr_dma_sts_cmp_clr_busy;
  end

  // Read data mux returns zero for addresses that do not map to a register.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (32'(reg_addr))
      LPARA_TMR_CTRL_OFFSET: w_rdata_nxt = w_tmr_ctrl_value;
      LPARA_TMR_PERIOD_OFFSET: w_rdata_nxt = w_tmr_period_value;
      LPARA_TMR_PERIOD_HI_OFFSET: w_rdata_nxt = w_tmr_period_hi_value;
      LPARA_TMR_PRESCALE_OFFSET: w_rdata_nxt = w_tmr_prescale_value;
      LPARA_TMR_DMA_CFG_OFFSET: w_rdata_nxt = w_tmr_dma_cfg_value;
      LPARA_TMR_CH0_CFG_OFFSET: w_rdata_nxt = w_tmr_ch0_cfg_value;
      LPARA_TMR_CH1_CFG_OFFSET: w_rdata_nxt = w_tmr_ch1_cfg_value;
      LPARA_TMR_CH2_CFG_OFFSET: w_rdata_nxt = w_tmr_ch2_cfg_value;
      LPARA_TMR_CH3_CFG_OFFSET: w_rdata_nxt = w_tmr_ch3_cfg_value;
      LPARA_TMR_CH4_CFG_OFFSET: w_rdata_nxt = w_tmr_ch4_cfg_value;
      LPARA_TMR_CH5_CFG_OFFSET: w_rdata_nxt = w_tmr_ch5_cfg_value;
      LPARA_TMR_CH6_CFG_OFFSET: w_rdata_nxt = w_tmr_ch6_cfg_value;
      LPARA_TMR_CH7_CFG_OFFSET: w_rdata_nxt = w_tmr_ch7_cfg_value;
      LPARA_TMR_CH0_CMP_OFFSET: w_rdata_nxt = w_tmr_ch0_cmp_value;
      LPARA_TMR_C0_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c0_cmp_h_value;
      LPARA_TMR_CH1_CMP_OFFSET: w_rdata_nxt = w_tmr_ch1_cmp_value;
      LPARA_TMR_C1_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c1_cmp_h_value;
      LPARA_TMR_CH2_CMP_OFFSET: w_rdata_nxt = w_tmr_ch2_cmp_value;
      LPARA_TMR_C2_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c2_cmp_h_value;
      LPARA_TMR_CH3_CMP_OFFSET: w_rdata_nxt = w_tmr_ch3_cmp_value;
      LPARA_TMR_C3_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c3_cmp_h_value;
      LPARA_TMR_CH4_CMP_OFFSET: w_rdata_nxt = w_tmr_ch4_cmp_value;
      LPARA_TMR_C4_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c4_cmp_h_value;
      LPARA_TMR_CH5_CMP_OFFSET: w_rdata_nxt = w_tmr_ch5_cmp_value;
      LPARA_TMR_C5_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c5_cmp_h_value;
      LPARA_TMR_CH6_CMP_OFFSET: w_rdata_nxt = w_tmr_ch6_cmp_value;
      LPARA_TMR_C6_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c6_cmp_h_value;
      LPARA_TMR_CH7_CMP_OFFSET: w_rdata_nxt = w_tmr_ch7_cmp_value;
      LPARA_TMR_C7_CMP_H_OFFSET: w_rdata_nxt = w_tmr_c7_cmp_h_value;
      LPARA_TMR_CNT_OFFSET: w_rdata_nxt = w_tmr_cnt_value;
      LPARA_TMR_CNT_HI_OFFSET: w_rdata_nxt = w_tmr_cnt_hi_value;
      LPARA_TMR_CAP_LVL_OFFSET: w_rdata_nxt = w_tmr_cap_lvl_value;
      LPARA_TMR_DMA_LVL_OFFSET: w_rdata_nxt = w_tmr_dma_lvl_value;
      LPARA_TMR_OPM_STS_OFFSET: w_rdata_nxt = w_tmr_opm_sts_value;
      LPARA_TMR_IRQ_RAW0_OFFSET: w_rdata_nxt = w_tmr_irq_raw0_value;
      LPARA_TMR_IRQ_EN0_OFFSET: w_rdata_nxt = w_tmr_irq_en0_value;
      LPARA_TMR_IRQ_INJ0_OFFSET: w_rdata_nxt = w_tmr_irq_inj0_value;
      LPARA_TMR_IRQ_STS0_OFFSET: w_rdata_nxt = w_tmr_irq_sts0_value;
      LPARA_TMR_IRQ_RAW1_OFFSET: w_rdata_nxt = w_tmr_irq_raw1_value;
      LPARA_TMR_IRQ_EN1_OFFSET: w_rdata_nxt = w_tmr_irq_en1_value;
      LPARA_TMR_IRQ_INJ1_OFFSET: w_rdata_nxt = w_tmr_irq_inj1_value;
      LPARA_TMR_IRQ_STS1_OFFSET: w_rdata_nxt = w_tmr_irq_sts1_value;
      LPARA_TMR_C0_TOUT_OFFSET: w_rdata_nxt = w_tmr_c0_tout_value;
      LPARA_TMR_C0_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c0_tout_h_value;
      LPARA_TMR_C1_TOUT_OFFSET: w_rdata_nxt = w_tmr_c1_tout_value;
      LPARA_TMR_C1_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c1_tout_h_value;
      LPARA_TMR_C2_TOUT_OFFSET: w_rdata_nxt = w_tmr_c2_tout_value;
      LPARA_TMR_C2_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c2_tout_h_value;
      LPARA_TMR_C3_TOUT_OFFSET: w_rdata_nxt = w_tmr_c3_tout_value;
      LPARA_TMR_C3_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c3_tout_h_value;
      LPARA_TMR_C4_TOUT_OFFSET: w_rdata_nxt = w_tmr_c4_tout_value;
      LPARA_TMR_C4_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c4_tout_h_value;
      LPARA_TMR_C5_TOUT_OFFSET: w_rdata_nxt = w_tmr_c5_tout_value;
      LPARA_TMR_C5_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c5_tout_h_value;
      LPARA_TMR_C6_TOUT_OFFSET: w_rdata_nxt = w_tmr_c6_tout_value;
      LPARA_TMR_C6_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c6_tout_h_value;
      LPARA_TMR_C7_TOUT_OFFSET: w_rdata_nxt = w_tmr_c7_tout_value;
      LPARA_TMR_C7_TOUT_H_OFFSET: w_rdata_nxt = w_tmr_c7_tout_h_value;
      LPARA_TMR_PI_CFG_OFFSET: w_rdata_nxt = w_tmr_pi_cfg_value;
      LPARA_TMR_P0_PER_OFFSET: w_rdata_nxt = w_tmr_p0_per_value;
      LPARA_TMR_P0_PER_H_OFFSET: w_rdata_nxt = w_tmr_p0_per_h_value;
      LPARA_TMR_P0_WID_OFFSET: w_rdata_nxt = w_tmr_p0_wid_value;
      LPARA_TMR_P0_WID_H_OFFSET: w_rdata_nxt = w_tmr_p0_wid_h_value;
      LPARA_TMR_P1_PER_OFFSET: w_rdata_nxt = w_tmr_p1_per_value;
      LPARA_TMR_P1_PER_H_OFFSET: w_rdata_nxt = w_tmr_p1_per_h_value;
      LPARA_TMR_P1_WID_OFFSET: w_rdata_nxt = w_tmr_p1_wid_value;
      LPARA_TMR_P1_WID_H_OFFSET: w_rdata_nxt = w_tmr_p1_wid_h_value;
      LPARA_TMR_P2_PER_OFFSET: w_rdata_nxt = w_tmr_p2_per_value;
      LPARA_TMR_P2_PER_H_OFFSET: w_rdata_nxt = w_tmr_p2_per_h_value;
      LPARA_TMR_P2_WID_OFFSET: w_rdata_nxt = w_tmr_p2_wid_value;
      LPARA_TMR_P2_WID_H_OFFSET: w_rdata_nxt = w_tmr_p2_wid_h_value;
      LPARA_TMR_P3_PER_OFFSET: w_rdata_nxt = w_tmr_p3_per_value;
      LPARA_TMR_P3_PER_H_OFFSET: w_rdata_nxt = w_tmr_p3_per_h_value;
      LPARA_TMR_P3_WID_OFFSET: w_rdata_nxt = w_tmr_p3_wid_value;
      LPARA_TMR_P3_WID_H_OFFSET: w_rdata_nxt = w_tmr_p3_wid_h_value;
      LPARA_TMR_PI_STS_OFFSET: w_rdata_nxt = w_tmr_pi_sts_value;
      LPARA_TMR_C0_OW_OFFSET: w_rdata_nxt = w_tmr_c0_ow_value;
      LPARA_TMR_C0_OW_H_OFFSET: w_rdata_nxt = w_tmr_c0_ow_h_value;
      LPARA_TMR_C1_OW_OFFSET: w_rdata_nxt = w_tmr_c1_ow_value;
      LPARA_TMR_C1_OW_H_OFFSET: w_rdata_nxt = w_tmr_c1_ow_h_value;
      LPARA_TMR_C2_OW_OFFSET: w_rdata_nxt = w_tmr_c2_ow_value;
      LPARA_TMR_C2_OW_H_OFFSET: w_rdata_nxt = w_tmr_c2_ow_h_value;
      LPARA_TMR_C3_OW_OFFSET: w_rdata_nxt = w_tmr_c3_ow_value;
      LPARA_TMR_C3_OW_H_OFFSET: w_rdata_nxt = w_tmr_c3_ow_h_value;
      LPARA_TMR_C4_OW_OFFSET: w_rdata_nxt = w_tmr_c4_ow_value;
      LPARA_TMR_C4_OW_H_OFFSET: w_rdata_nxt = w_tmr_c4_ow_h_value;
      LPARA_TMR_C5_OW_OFFSET: w_rdata_nxt = w_tmr_c5_ow_value;
      LPARA_TMR_C5_OW_H_OFFSET: w_rdata_nxt = w_tmr_c5_ow_h_value;
      LPARA_TMR_C6_OW_OFFSET: w_rdata_nxt = w_tmr_c6_ow_value;
      LPARA_TMR_C6_OW_H_OFFSET: w_rdata_nxt = w_tmr_c6_ow_h_value;
      LPARA_TMR_C7_OW_OFFSET: w_rdata_nxt = w_tmr_c7_ow_value;
      LPARA_TMR_C7_OW_H_OFFSET: w_rdata_nxt = w_tmr_c7_ow_h_value;
      LPARA_TMR_DMA_STS_OFFSET: w_rdata_nxt = w_tmr_dma_sts_value;
      default: begin
        w_rdata_nxt = '0;
      end
    endcase
  end

  // Read response storage follows the selected clock architecture.
  generate
    if (PARA_ASYNCHRONOUS == 32'd1) begin : g_async_rdata
      logic [LPARA_DATA_W-1:0] reg_rdata_bus;

      // Snapshot read data in the register clock domain.
      always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
        if (!i_rst_n_reg)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end

      // The synchronized acknowledge qualifies the stable bundled read data.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
        if (!i_rst_n_apb)
          reg_rdata_bus <= '0;
        else if (w_rd_ack_fall)
          reg_rdata_bus <= reg_rdata;
      end
      assign o_apb_prdata = reg_rdata_bus;
    end else begin : g_sync_rdata
      // Synchronous read data is captured in the APB/register clock domain.
      always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata
        if (!i_rst_n_apb)
          reg_rdata <= '0;
        else if (w_rd_en)
          reg_rdata <= w_rdata_nxt;
      end
      assign o_apb_prdata = reg_rdata;
    end
  endgenerate

endmodule
